    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
]);

editar("lang/en/carriers.json", [
    [base64_decode(''), base64_decode('')],
]);

editar("lang/es/carriers.json", [
    [base64_decode(''), base64_decode('')],
]);

editar("resources/js/pages/App/Carriers/Form.tsx", [
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode(''), base64_decode('')],
    [base64_decode('ICAgICAgPGRpdiBjbGFzc05hbWU9Im10LTIgZ3JpZCBnYXAtNCBzbTpncmlkLWNvbHMtMiI+e2NoaWxkcmVufTwvZGl2PgogICAgPC9maWVsZHNldD4KICApCn0K'), base64_decode('')],
]);

/* ── Parte ───────────────────────────────────────────────────────────────── */

echo $dry ? "SIMULACIÓN (no se escribió nada)\n\n" : "lote13 — alta por DOT contra FMCSA\n\n";

foreach ($hechos as $l) {
    echo "  {$l}\n";
}

if ($saltados !== []) {
    echo "\n  ya estaba:\n";
    foreach ($saltados as $l) {
        echo "    {$l}\n";
    }
}

if ($errores !== []) {
    echo "\nERRORES:\n";
    foreach ($errores as $l) {
        echo "  ! {$l}\n";
    }
    echo "\nNada de lo que falló se escribió a medias.\n";
    exit(1);
}

if (! $dry) {
    echo <<<'TXT'

Siguiente paso, en este orden:

  npm run build          # el formulario de transportista cambió
  ./vendor/bin/pest

No hay migración en este lote.

Cuando tengas la clave de FMCSA, va en el .env DEL SERVIDOR (no aquí, no en
el chat, no en el repositorio):

  FMCSA_WEBKEY=...

Sin ella la aplicación sigue funcionando con el adaptador simulado, y lo dice
en pantalla.

TXT;
}

exit(0);
